      "type": "ReactNode",
      "required": false,
      "description": "Mark rendered above the card."
    },
    {
      "name": "logo",
      "type": "ReactNode",
      "required": false,
      "description": "Alias for brand (migration-friendly)."
    },
    {
      "name": "footer",
      "type": "ReactNode",
      "required": false,
